        void remember(BlockPos p){if(!level.isOutsideBuildHeight(p))blocks.computeIfAbsent(p.immutable(),at->game.maps().snapshot(level,at));}
        void initialize(){for(int x=(center.getX()-17)>>4;x<=(center.getX()+17)>>4;x++)for(int z=(center.getZ()-17)>>4;z<=(center.getZ()+17)>>4;z++){long key=net.minecraft.world.level.ChunkPos.pack(x,z);if(!level.getForceLoadedChunks().contains(key)){forced.add(key);level.setChunkForced(x,z,true);}var chunk=level.getChunkAt(new BlockPos(x*16,center.getY(),z*16));((net.minecraft.world.ticks.LevelChunkTicks<Block>)chunk.getBlockTicks()).getAll().filter(t->tickBounds.isInside(t.pos())).forEach(originalBlockTicks::add);((net.minecraft.world.ticks.LevelChunkTicks<Fluid>)chunk.getFluidTicks()).getAll().filter(t->tickBounds.isInside(t.pos())).forEach(originalFluidTicks::add);}
            for(var p:BlockPos.betweenClosed(center.offset(-16,-26,-16),center.offset(16,62,16)))remember(p);
            for(var p:List.of(alpha,beta)){p.closeContainer();p.getInventory().clearContent();p.removeAllEffects();p.setGameMode(GameType.SURVIVAL);p.setNoGravity(true);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);p.setHealth(1000);p.setAbsorptionAmount(0);p.setInvulnerableTime(0);p.damageCooldownTime=0;}
            clear();place();lastTick=game.server().getTickCount();}
        void place(){alpha.teleportTo(level,origin.x+60,origin.y,origin.z,Set.of(),0,0,true);beta.teleportTo(level,origin.x,origin.y,origin.z,Set.of(),0,0,true);}
        void clear(){for(var e:new ArrayList<>(actors)){if(e instanceof LivingEntity living)game.items().indirectKills().clear(living);e.discard();}actors.clear();tokens.forEach(Entity::discard);level.getBlockTicks().clearArea(tickBounds);level.getFluidTicks().clearArea(tickBounds);for(var p:blocks.keySet())if(!level.getBlockState(p).isAir()){if(level.getBlockEntity(p) instanceof net.minecraft.world.Container c)c.clearContent();level.setBlock(p,Blocks.AIR.defaultBlockState(),818);}beta.removeEffect(net.minecraft.world.effect.MobEffects.RESISTANCE);alpha.removeEffect(net.minecraft.world.effect.MobEffects.RESISTANCE);place();}
