        int low(LbcIslandDropItem.Kind kind){return kind==LbcIslandDropItem.Kind.RAISE?-15:-12;}
        int high(LbcIslandDropItem.Kind kind){return kind==LbcIslandDropItem.Kind.RAISE?15:0;}
        int dy(LbcIslandDropItem.Kind kind){return kind==LbcIslandDropItem.Kind.RAISE?46:-13;}
