            for(var kind:LbcIslandDropItem.Kind.values())for(int hazard=0;hazard<3;hazard++){clear();var c=cow(origin.add(0,-2,0));var block=hazard==0?Blocks.STONE:hazard==1?Blocks.LAVA:Blocks.WATER;for(int y=-3;y<=(kind==LbcIslandDropItem.Kind.RAISE?2:0);y++)set(center.above(y),block.defaultBlockState());activate(kind);require(level.getBlockState(BlockPos.containing(c.getEyePosition())).is(block),"actual cloned destination hazard surrounds moved mob");lethal(c,hazard==0?c.damageSources().inWall():hazard==1?c.damageSources().lava():c.damageSources().drown(),alpha);}
